#!/usr/bin/env bash
# Fast verification checks for this repo, generated by /quorum:init-pipeline.
# The Quorum Stop hook runs this before Claude or the builder may finish a task. It must exit 0 only when every
# check passes. Keep it fast (typecheck, lint, unit tests); slow suites belong in a task's eval.md.
# Keep it in sync with the "## Verification Commands" section of CLAUDE.md.
set -uo pipefail
cd "$(dirname "$0")/../.." || exit 1

failed=""
check() {
  echo "== $1: $2"
  if ! bash -c "$2"; then failed="$failed $1"; fi
}

check typecheck 't=$(mktemp -d); git ls-files -co --exclude-standard | while IFS= read -r f; do [ -e "$f" ] && mkdir -p "$t/$(dirname "$f")" && cp -p "$f" "$t/$f"; done; claude plugin validate --strict "$t"; s=$?; rm -rf "$t"; exit $s'
check lint 'shellcheck hooks/*.sh bin/* libexec/* evals/run.sh evals/_fixture/make.sh evals/*/scaffold.sh assets/src/*.sh'
check test 'claude plugin test .'

if [ -n "$failed" ]; then
  echo "FAILED:$failed" >&2
  exit 1
fi
echo "All checks passed."
